package pe.vichaval.gestionriego.auditoria.controller;
import java.time.LocalDate;import org.springframework.data.domain.Page;import org.springframework.format.annotation.DateTimeFormat;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import pe.vichaval.gestionriego.auditoria.service.AuditoriaService;
@Controller @RequestMapping("/auditoria") @PreAuthorize("hasRole('ADMINISTRADOR')") public class AuditoriaWebController{private final AuditoriaService auditoria;public AuditoriaWebController(AuditoriaService a){auditoria=a;}
 @GetMapping public String listar(@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="")String usuario,@RequestParam(defaultValue="")String metodo,@RequestParam(defaultValue="")String ruta,@RequestParam(defaultValue="")String correlacionId,@RequestParam(defaultValue="")String familiaHttp,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate fechaDesde,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate fechaHasta,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="25")int size,Model m){
  try{var p=auditoria.buscar(q,usuario,metodo,ruta,correlacionId,familiaHttp,fechaDesde,fechaHasta,page,size);m.addAttribute("pagina",p);m.addAttribute("size",p.getSize());}catch(IllegalArgumentException ex){m.addAttribute("error",ex.getMessage());m.addAttribute("pagina",Page.empty());m.addAttribute("size",25);}m.addAttribute("q",q);m.addAttribute("usuario",usuario);m.addAttribute("metodo",metodo);m.addAttribute("ruta",ruta);m.addAttribute("correlacionId",correlacionId);m.addAttribute("familiaHttp",familiaHttp);m.addAttribute("fechaDesde",fechaDesde);m.addAttribute("fechaHasta",fechaHasta);return "auditoria/index";}
}
